// Open-Meteo forecast for one place, cut down to what a weather picture draws:
// the conditions now, the next two days hour by hour and a week day by day.
// No key needed. Times come back as epoch milliseconds; `offset` is the place's
// UTC offset in seconds, so a view can tell the place's own clock time
// whatever time zone the frame is in.

function wallClockMs(text: string) {
  // "2026-11-23T09:00" or "2026-11-23": the place's wall clock, read as UTC.
  const year = Number(text.substring(0, 4))
  const month = Number(text.substring(5, 7)) - 1
  const day = Number(text.substring(8, 10))
  const hour = text.length > 10 ? Number(text.substring(11, 13)) : 0
  const minute = text.length > 13 ? Number(text.substring(14, 16)) : 0
  return Date.UTC(year, month, day, hour, minute)
}

function findPlace(query: string) {
  // "50.85, 4.35" skips the lookup.
  const pair = query.match(/^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$/)
  if (pair) {
    return { query, name: '', country: '', latitude: Number(pair[1]), longitude: Number(pair[2]) }
  }
  const known = frameos.recall('place')
  if (known && known.query === query) {
    return known
  }
  const answer = frameos.fetchJson(
    'https://geocoding-api.open-meteo.com/v1/search?count=1&format=json&name=' + encodeURIComponent(query),
  )
  const hit = answer && answer.results && answer.results[0]
  if (!hit) {
    throw new Error('Place not found: ' + query)
  }
  const place = {
    query,
    name: hit.name || query,
    country: hit.country || '',
    latitude: hit.latitude,
    longitude: hit.longitude,
  }
  frameos.remember('place', place)
  return place
}

function rounded(values: number[], digits: number) {
  const scale = Math.pow(10, digits)
  return (values || []).map((value) => (value == null ? null : Math.round(value * scale) / scale))
}

export function get(app: FrameOSApp) {
  const query = String(app.config.location || '').trim()
  if (!query) {
    throw new Error('Set a location')
  }
  const place = findPlace(query)
  const fahrenheit = app.config.temperatureUnit === 'fahrenheit'
  const windUnit = app.config.windSpeedUnit || 'kmh'
  const precipUnit = app.config.precipitationUnit || 'mm'
  const url =
    'https://api.open-meteo.com/v1/forecast?latitude=' + place.latitude +
    '&longitude=' + place.longitude +
    '&timezone=auto&forecast_days=7&past_hours=2&forecast_hours=50' +
    '&temperature_unit=' + (fahrenheit ? 'fahrenheit' : 'celsius') +
    '&wind_speed_unit=' + windUnit +
    '&precipitation_unit=' + precipUnit +
    '&current=temperature_2m,apparent_temperature,weather_code,cloud_cover,is_day,precipitation,' +
    'wind_speed_10m,wind_gusts_10m,wind_direction_10m,relative_humidity_2m' +
    '&hourly=temperature_2m,apparent_temperature,precipitation_probability,precipitation,weather_code,' +
    'cloud_cover,wind_speed_10m,wind_direction_10m,is_day' +
    '&daily=weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,precipitation_sum,' +
    'precipitation_probability_max,wind_speed_10m_max'
  const data = frameos.fetchJson(url)
  if (!data || data.error || !data.hourly || !data.daily) {
    throw new Error(data && data.reason ? data.reason : 'No forecast for ' + query)
  }
  const offset = data.utc_offset_seconds || 0
  const toEpoch = (text: string) => wallClockMs(text) - offset * 1000
  const now = data.current || {}
  const hourly = data.hourly
  const daily = data.daily
  return {
    place: place.name,
    country: place.country,
    latitude: place.latitude,
    longitude: place.longitude,
    offset,
    fahrenheit,
    units: {
      temperature: fahrenheit ? '°F' : '°C',
      wind: { kmh: 'km/h', ms: 'm/s', mph: 'mph', kn: 'kn' }[windUnit] || windUnit,
      precipitation: precipUnit === 'inch' ? 'in' : 'mm',
    },
    current: {
      time: now.time ? toEpoch(now.time) : Date.now(),
      temperature: now.temperature_2m,
      feelsLike: now.apparent_temperature,
      code: now.weather_code,
      cloud: now.cloud_cover,
      isDay: now.is_day === 1,
      precipitation: now.precipitation,
      wind: now.wind_speed_10m,
      gusts: now.wind_gusts_10m,
      windDirection: now.wind_direction_10m,
      humidity: now.relative_humidity_2m,
    },
    hourly: {
      start: toEpoch(hourly.time[0]),
      temperature: rounded(hourly.temperature_2m, 1),
      feelsLike: rounded(hourly.apparent_temperature, 1),
      rainChance: hourly.precipitation_probability,
      precipitation: rounded(hourly.precipitation, 2),
      code: hourly.weather_code,
      cloud: hourly.cloud_cover,
      wind: rounded(hourly.wind_speed_10m, 0),
      windDirection: hourly.wind_direction_10m,
      isDay: hourly.is_day,
    },
    daily: {
      start: toEpoch(daily.time[0]),
      high: rounded(daily.temperature_2m_max, 1),
      low: rounded(daily.temperature_2m_min, 1),
      code: daily.weather_code,
      sunrise: daily.sunrise.map(toEpoch),
      sunset: daily.sunset.map(toEpoch),
      precipitation: rounded(daily.precipitation_sum, 1),
      rainChance: daily.precipitation_probability_max,
      wind: rounded(daily.wind_speed_10m_max, 0),
    },
  }
}

